(function() {
    'use strict';

    class StartupBlueprintAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Startup Blueprint: Health-Tech Venture';
            this.version = '1.1.0';

            this.MARKET_EVENTS = [
                { key: 'briefing_1', demandMod: 1.0, costMod: 1.0 },
                { key: 'briefing_2', demandMod: 1.05, costMod: 1.0 },
                { key: 'briefing_3', demandMod: 0.9, costMod: 1.0 },
                { key: 'briefing_4', demandMod: 0.95, costMod: 1.12 },
                { key: 'briefing_5', demandMod: 1.25, costMod: 1.0 },
                { key: 'briefing_6', demandMod: 1.1, costMod: 0.95 },
                { key: 'briefing_7', demandMod: 1.15, costMod: 1.0 },
                { key: 'briefing_8', demandMod: 0.8, costMod: 1.05 },
                { key: 'briefing_9', demandMod: 1.2, costMod: 1.0 },
                { key: 'briefing_10', demandMod: 1.1, costMod: 0.98 },
                { key: 'briefing_11', demandMod: 1.15, costMod: 1.0 },
                { key: 'briefing_12', demandMod: 1.0, costMod: 1.0 }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 500000,
                    activeUsers: 0,
                    mrrValue: 0,
                    totalRevenue: 0,
                    churnRate: 0.08,
                    productQuality: 50,
                    competitorUsers: 11100000,
                    lastCac: 0,
                    lastLtv: 0,
                    lastLtvCacRatio: 0,
                    lastRunway: 99,
                    lastMarketShare: 0,
                    mrrHistory: [],
                    usersHistory: [],
                    cashHistory: [],
                    profitHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    marketingBudget: 25000,
                    channelStrategy: 'balanced',
                    productFocus: 'core',
                    monthlyPrice: 12.99
                };
            }
            var self = this;
            var sim = window.mySimulation;
            if (sim && sim.eventBus && typeof sim.eventBus.on === 'function' && !this._reactBound) {
                // FIX(v1.1.0): undo restores state but never re-invokes the view, and
                // language changes should re-render the (localized) market-event
                // briefing. Keep the briefing reactive to both.
                this._reactBound = true;
                sim.eventBus.on('period:undone', function(st) { self._updateBriefing(st || sim.state); });
                sim.eventBus.on('language:changed', function() { self._updateBriefing(sim.state); });
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var budgetInput = document.getElementById('marketingBudgetInput');
            if (budgetInput) decisions.marketingBudget = parseFloat(budgetInput.value);

            var channelInput = document.getElementById('channelStrategySelect');
            if (channelInput) decisions.channelStrategy = channelInput.value;

            var focusInput = document.getElementById('productFocusSelect');
            if (focusInput) decisions.productFocus = focusInput.value;

            var priceInput = document.getElementById('monthlyPriceInput');
            if (priceInput) decisions.monthlyPrice = parseFloat(priceInput.value);

            if (!decisions.marketingBudget || decisions.marketingBudget < 5000 || decisions.marketingBudget > 50000) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_warning'), 'warning'
                );
                return false;
            }

            if (!decisions.monthlyPrice || decisions.monthlyPrice < 4.99 || decisions.monthlyPrice > 29.99) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('price_warning'), 'warning'
                );
                return false;
            }

            var currentState = window.mySimulation.state;
            if (currentState && currentState.domainState && currentState.domainState.cash <= 0) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('bankrupt_warning'), 'danger'
                );
                return false;
            }

            // FIX(v1.1.0): removed a redundant _updateBriefing() here (it re-rendered
            // the briefing on every validate/preview). The next month is rendered by
            // calculateResults; the decision inputs are static and read above.
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var periodIdx = Math.min((state.currentPeriod || 1) - 1, this.MARKET_EVENTS.length - 1);
            var event = this.MARKET_EVENTS[periodIdx];

            var cac, acquisitionSpeed;
            switch (d.channelStrategy) {
                case 'organic':
                    cac = 3.5 + Math.random() * 2;
                    acquisitionSpeed = 0.6;
                    break;
                case 'paid':
                    cac = 10 + Math.random() * 5;
                    acquisitionSpeed = 1.3;
                    break;
                case 'b2b':
                    cac = 25 + Math.random() * 15;
                    acquisitionSpeed = 0.35;
                    break;
                default:
                    cac = 8 + Math.random() * 4;
                    acquisitionSpeed = 1.0;
                    break;
            }

            var rawAcquired = Math.floor(d.marketingBudget / cac * acquisitionSpeed);
            var priceEffect = Math.max(0.3, 1 - (d.monthlyPrice - 9.99) / 40);
            var demandMultiplier = event.demandMod;
            var qualityBonus = Math.max(0.5, ds.productQuality / 80);
            var newUsers = Math.max(0, Math.round(rawAcquired * priceEffect * demandMultiplier * qualityBonus));

            var churnAdjust = 0;
            var qualityGain = 0;
            switch (d.productFocus) {
                case 'core':
                    churnAdjust = -0.008;
                    qualityGain = 7;
                    break;
                case 'retention':
                    churnAdjust = -0.02;
                    qualityGain = 4;
                    break;
                case 'monetization':
                    churnAdjust = 0.008;
                    qualityGain = 2;
                    break;
                case 'integrations':
                    churnAdjust = -0.005;
                    qualityGain = 5;
                    break;
            }

            ds.productQuality = Math.min(100, ds.productQuality + qualityGain);
            var qualityChurnBonus = (ds.productQuality - 50) * 0.0004;
            ds.churnRate = Math.max(0.02, Math.min(0.15, ds.churnRate + churnAdjust - qualityChurnBonus));

            if (d.channelStrategy === 'b2b') {
                ds.churnRate = Math.max(0.01, ds.churnRate * 0.5);
            }

            var churned = Math.round(ds.activeUsers * ds.churnRate);
            ds.activeUsers = Math.max(0, ds.activeUsers + newUsers - churned);

            var grossMargin = 0.72;
            var b2bRevenueMultiplier = d.channelStrategy === 'b2b' ? 2.5 : 1.0;
            var monthlyRevenue = ds.activeUsers * d.monthlyPrice * grossMargin * b2bRevenueMultiplier;

            var fixedCosts = 45000 * event.costMod;
            var totalCosts = fixedCosts + d.marketingBudget;
            var profit = monthlyRevenue - totalCosts;

            ds.cash = Math.round(ds.cash + profit);
            ds.mrrValue = Math.round(ds.activeUsers * d.monthlyPrice * b2bRevenueMultiplier);
            ds.totalRevenue += monthlyRevenue;

            ds.competitorUsers = Math.round(ds.competitorUsers * (1 + 0.004 + Math.random() * 0.006));
            var totalMarketUsers = ds.activeUsers + ds.competitorUsers;
            var marketShare = totalMarketUsers > 0 ? (ds.activeUsers / totalMarketUsers) * 100 : 0;

            var ltv = ds.churnRate > 0 ? (d.monthlyPrice * grossMargin * b2bRevenueMultiplier / ds.churnRate) : 0;
            var ltvCacRatio = cac > 0 ? ltv / cac : 0;

            var runway = profit < 0 ? Math.max(0, ds.cash / Math.abs(profit)) : 99;

            ds.lastCac = Math.round(cac * 100) / 100;
            ds.lastLtv = Math.round(ltv);
            ds.lastLtvCacRatio = Math.round(ltvCacRatio * 10) / 10;
            ds.lastRunway = Math.round(runway * 10) / 10;
            ds.lastMarketShare = Math.round(marketShare * 100) / 100;

            ds.mrrHistory.push(Math.round(ds.mrrValue));
            ds.usersHistory.push(ds.activeUsers);
            ds.cashHistory.push(Math.round(ds.cash));
            ds.profitHistory.push(Math.round(profit));

            var panel = document.getElementById('resultsPanel');
            if (panel) panel.style.display = 'block';

            // FIX(v1.1.0): advance the market-event briefing synchronously. The
            // previous setTimeout closure read state.currentPeriod AFTER the framework
            // incremented it, so it showed month N+2 — the player was briefed on the
            // wrong month's market event while its demand/cost modifiers silently
            // applied. Guard on state identity so the deep-cloned competition preview
            // never mutates the live DOM.
            if (window.mySimulation && state === window.mySimulation.state) {
                var nextPeriod = (state.currentPeriod || 1) + 1;
                if (nextPeriod <= this.MARKET_EVENTS.length) {
                    this._updateBriefing({ currentPeriod: nextPeriod });
                }
            }

            return {
                period: state.currentPeriod,
                newUsers: newUsers,
                churned: churned,
                activeUsers: ds.activeUsers,
                cac: ds.lastCac,
                churnRate: Math.round(ds.churnRate * 1000) / 10,
                mrr: ds.mrrValue,
                revenue: Math.round(monthlyRevenue),
                costs: Math.round(totalCosts),
                profit: Math.round(profit),
                cash: ds.cash,
                marketShare: ds.lastMarketShare,
                ltv: ds.lastLtv,
                ltvCacRatio: ds.lastLtvCacRatio,
                runway: ds.lastRunway
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash',
                function(v) { return '$' + Math.round(v).toLocaleString(); });
            uiManager.bind('activeUsersDisplay', 'domainState.activeUsers',
                function(v) { return v.toLocaleString(); });
            uiManager.bind('mrrDisplay', 'domainState.mrrValue',
                function(v) { return '$' + Math.round(v).toLocaleString(); });
            uiManager.bind('runwayDisplay', 'domainState.lastRunway',
                function(v) { return v >= 99 ? '99+' : v.toFixed(1); });
            uiManager.bind('marketShareDisplay', 'domainState.lastMarketShare',
                function(v) { return v.toFixed(2) + '%'; });
            uiManager.bind('ltvCacDisplay', 'domainState.lastLtvCacRatio',
                function(v) { return v > 0 ? v.toFixed(1) + 'x' : '--'; });
            uiManager.bind('newUsersDisplay', 'results.newUsers',
                function(v) { return '+' + v.toLocaleString(); });
            uiManager.bind('churnedDisplay', 'results.churned',
                function(v) { return '-' + v.toLocaleString(); });
            uiManager.bind('cacDisplay', 'results.cac',
                function(v) { return '$' + v.toFixed(2); });
            uiManager.bind('churnRateDisplay', 'results.churnRate',
                function(v) { return v.toFixed(1) + '%'; });
            uiManager.bind('revenueDisplay', 'results.revenue',
                function(v) { return '$' + Math.round(v).toLocaleString(); });
            uiManager.bind('profitDisplay', 'results.profit',
                function(v) { return (v >= 0 ? '+$' : '-$') + Math.abs(Math.round(v)).toLocaleString(); });
        }

        getChartConfig() {
            return {
                mrrChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'MRR ($)',
                            data: [],
                            borderColor: '#ff9800',
                            backgroundColor: 'rgba(255,152,0,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3
                        }, {
                            label: 'Profit ($)',
                            data: [],
                            borderColor: '#4caf50',
                            backgroundColor: 'rgba(76,175,80,0.1)',
                            borderWidth: 2,
                            fill: false,
                            tension: 0.3
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Revenue and Profit', color: '#e0e0e0' },
                            legend: { labels: { color: '#b0bec5' } }
                        },
                        scales: {
                            x: { ticks: { color: '#78909c' }, grid: { color: 'rgba(255,255,255,0.05)' } },
                            y: { beginAtZero: true, ticks: { color: '#78909c' }, grid: { color: 'rgba(255,255,255,0.08)' } }
                        }
                    }
                },
                usersChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Active Users',
                            data: [],
                            backgroundColor: 'rgba(33,150,243,0.6)',
                            borderColor: '#2196f3',
                            borderWidth: 1
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'User Growth', color: '#e0e0e0' },
                            legend: { labels: { color: '#b0bec5' } }
                        },
                        scales: {
                            x: { ticks: { color: '#78909c' }, grid: { color: 'rgba(255,255,255,0.05)' } },
                            y: { beginAtZero: true, ticks: { color: '#78909c' }, grid: { color: 'rgba(255,255,255,0.08)' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.mrrHistory.map(function(_, i) { return 'M' + (i + 1); });
            return {
                mrrChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.mrrHistory },
                        { data: state.domainState.profitHistory }
                    ]
                },
                usersChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.usersHistory }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var profits = history.map(function(r) { return r.results ? r.results.profit || 0 : 0; });
            var totalProfit = profits.reduce(function(s, p) { return s + p; }, 0);
            var avgProfit = totalProfit / profits.length;
            var finalMrr = history[history.length - 1].results ? history[history.length - 1].results.mrr || 0 : 0;
            var finalUsers = history[history.length - 1].results ? history[history.length - 1].results.activeUsers || 0 : 0;
            var finalCash = history[history.length - 1].results ? history[history.length - 1].results.cash || 0 : 0;
            var finalLtvCac = history[history.length - 1].results ? history[history.length - 1].results.ltvCacRatio || 0 : 0;

            var performance = 'Struggling Startup';
            var insights = [];

            if (finalCash <= 0) {
                performance = 'Bankrupt';
                insights.push('The startup ran out of cash. Cash management and burn rate control are critical for survival.');
            } else if (finalMrr > 200000 && finalLtvCac > 3 && avgProfit > 0) {
                performance = 'Unicorn Potential';
                insights.push('Outstanding execution with strong unit economics and rapid growth.');
                insights.push('With an LTV/CAC ratio above 3x and positive margins, this startup is investor-ready.');
            } else if (finalMrr > 100000 && finalLtvCac > 2) {
                performance = 'Growth Stage Ready';
                insights.push('Solid growth trajectory with healthy unit economics.');
                insights.push('Consider optimizing channel mix to further improve CAC efficiency.');
            } else if (finalMrr > 50000 && avgProfit > -20000) {
                performance = 'Finding Product-Market Fit';
                insights.push('The startup is gaining traction but unit economics need improvement.');
                insights.push('Focus on reducing churn and improving retention to increase LTV.');
            } else {
                insights.push('Growth was slower than expected. Review channel strategy and pricing.');
                insights.push('Consider whether the target segment and pricing model are aligned.');
            }

            return {
                totalProfit: Math.round(totalProfit),
                averageMonthlyProfit: Math.round(avgProfit),
                finalMrr: Math.round(finalMrr),
                finalActiveUsers: finalUsers,
                cashRemaining: Math.round(finalCash),
                finalLtvCacRatio: finalLtvCac,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (results.cash <= 0) {
                return window.mySimulation.t('hint_bankrupt');
            }
            if (results.runway < 4 && results.runway < 99) {
                return window.mySimulation.t('hint_low_runway');
            }
            if (results.ltvCacRatio < 1.5 && results.ltvCacRatio > 0) {
                return window.mySimulation.t('hint_low_ltv_cac');
            }
            if (results.churnRate > 10) {
                return window.mySimulation.t('hint_high_churn');
            }
            if (results.profit > 0 && results.mrr > 50000) {
                return window.mySimulation.t('hint_strong');
            }
            if (results.newUsers < 500 && state.currentPeriod > 3) {
                return window.mySimulation.t('hint_slow_growth');
            }
            return null;
